// ─────────────────────────────────────────────────────────────────────────────
// GRAPH-DRIVEN TEMPLATE SITE
//
// The Project Graph is the REAL runtime. A template site is a graph whose nodes
// are the template's sections (blades) in order; each node's content carries the
// WORDS (an array of slot values, by position, matching the blade's d[] defaults).
// The design (shell + CSS + interactions) is the library; every WORD is graph
// content, so re-wording = a content patch, never a hand-edited page.
//
// Content shape (each blade id in NX_TEMPLATE_ORDER):
//   content = { blade: 'hero', slots: [ ...words... ] }   // slots[ i ] overrides default i
// Optional top-level `config` (phones/email/businessName/...) feeds the runtime.
// ─────────────────────────────────────────────────────────────────────────────
function nxTemplateProject(words) {
  // Build a graph-like project: order + nodes + content + a config node.
  const order = [];
  const nodes = {};
  const content = {};
  const blades = NX_TEMPLATE_ORDER;
  const make = (id, i) => {
    const blade = { blade: id, slots: null };
    nodes[id] = {
      id, family: 'template', semanticRole: i === 0 ? 'section' : 'section',
      parent: null, children: [], component: { family: 'template' },
      content: blade, props: {}, constraints: {}, states: {}, interactions: {}, motion: {}, design: {},
    };
    content[id] = blade;
    return id;
  };
  blades.forEach((id, i) => { order.push(make(id, i)); nodes[id].parent = '__root__'; });
  nodes['__root__'] = { id: '__root__', family: 'container', semanticRole: 'section', parent: null, children: order, component: { family: 'container' }, content: {}, props: {}, constraints: {}, states: {}, interactions: {}, motion: {}, design: {} };
  // Apply words: if `words` is per-blade (object keyed by blade id with slots array),
  // set the slot arrays; if a blade has no override, it keeps the template wording.
  if (words) {
    for (const id of blades) {
      const w = words[id];
      if (Array.isArray(w)) { content[id].slots = w.slice(); }
      else if (w && typeof w === 'object' && w.slots) { content[id].slots = w.slots.slice(); }
    }
  }
  // Auto-derive runtime config from the words' top-level contact/business fields
  // so the template runtime (phones/email/applyCfgToPage) stays in sync with the
  // authored words. An explicit words.config always wins.
  const w = words || {};
  const cfg = (typeof w.config === 'object' && w.config) || {};
  if (w.phone) cfg.phone = w.phone;
  if (w.email) cfg.email = w.email;
  // Accept `business` as well as `businessName`: callers (and nxPlanToWords)
  // use the short key, and dropping it left the reference client's name as the
  // project name, which then defeated identity substitution downstream.
  if (w.businessName || w.business) cfg.businessName = w.businessName || w.business;
  if (w.owner || w.ownerName) cfg.ownerName = w.owner || w.ownerName;
  if (w.industry) cfg.industry = w.industry;
  if (w.address) cfg.base = cfg.base || w.address;
  if (w.years !== undefined) cfg.years = String(w.years);
  if (w.coverage) cfg.coverage = w.coverage;
  if (w.base) cfg.base = w.base;
  if (Array.isArray(w.phones)) cfg.phones = w.phones.slice();
  else if (w.phone) cfg.phones = [w.phone];
  // Never fall back to the reference client's real business name.
  return { name: w.name || w.business || cfg.businessName || 'Your Business', order: ['__root__'], nodes, content, config: Object.keys(cfg).length ? cfg : null };
}

// Render a single blade node to HTML, filling slots from its graph content.
function nxRenderTemplateNode(project, id) {
  const c = project.content[id];
  if (!c || !c.blade) return '';
  return nxRenderBlade(c.blade, c.slots || null);
}

// Compile a template project into a full HTML document.
// Build the runtime script, merging (never replacing) graph-supplied config over
// the template's own DEFAULT_CFG. DEFAULT_CFG keeps all its fields; the graph's
// live config (phones/phone/email/businessName/...) is Object.assign'd on top so
// the runtime never reads undefined and the blades stay in sync with the config.
function windowScriptGuard(cfg) {
  if (!cfg) return NX_SCRIPT;
  const json = JSON.stringify(cfg);
  // Inject right before `let CFG=loadCfg();` (which precomputes DEFAULT_CFG) so the
  // graph overrides are part of the defaults that loadCfg() then spreads.
  const anchor = 'let CFG=loadCfg();';
  const inject = 'Object.assign(DEFAULT_CFG, ' + json + ');\n' + anchor;
  if (NX_SCRIPT.indexOf(anchor) !== -1) return NX_SCRIPT.replace(anchor, inject);
  // Fallback: prepend the assignment just after the DEFAULT_CFG definition marker.
  const cfgAnchor = '/*cfg29*/';
  if (NX_SCRIPT.indexOf(cfgAnchor) !== -1) return NX_SCRIPT.replace(cfgAnchor, cfgAnchor + '\nObject.assign(DEFAULT_CFG, ' + json + ');');
  return NX_SCRIPT;
}

function nxRenderTemplateDocument(project, opts) {
  opts = opts || {};
  const bp = opts.breakpoint || 'desktop';
  const roots = project.order || [];
  const body = [];
  for (const rid of roots) {
    const rn = project.nodes[rid];
    if (!rn) continue;
    for (const cid of (rn.children || [])) body.push(nxRenderTemplateNode(project, cid));
  }
  const main = body.join('');
  const css = NX_CSS;
  const head = NX_HEAD;
  // Inject config into the runtime so it reads graph-supplied contact/business data.
  const cfgJson = (project.config && Object.keys(project.config).length)
    ? '<script>window.__NX_CFG=' + JSON.stringify(project.config) + ';</script>\n' : '';
  // Graph-supplied config is MERGED over the template's DEFAULT_CFG (never replaces
  // it), so fields the graph doesn't set (phones, services, knowledge, ...) are
  // preserved and the runtime never reads undefined.
  const cfg = project && project.config && Object.keys(project.config).length ? project.config : null;
  const script = windowScriptGuard(cfg);
  let html = '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
    + head + '<title>' + String(project.name || 'Your Business').replace(/&/g,'&amp;').replace(/</g,'&lt;') + '</title>'
    + '<style>' + css + '</style></head><body>' + main + cfgJson + '<script>' + script + '</script></body></html>';

  // ── IDENTITY BOUNDARY (mandatory) ──────────────────────────────────────
  // This template is a real, finished site design we keep as a default style.
  // Its ORIGINAL CLIENT'S identity — business name, owner, phone, email,
  // postal address and industry copy — is baked into the markup, CSS content
  // strings and the runtime script. Rendering it for anyone else previously
  // shipped that real business's contact details inside their website.
  //
  // The design passes through; the identity does not. This runs unconditionally
  // so no future call path can opt out of it by forgetting a flag.
  let scrubbedJs = script;
  try {
    const __id = (typeof require === 'function') ? require('./nx_identity.js') : null;
    if (__id) {
      // Collect the words the CALLER supplied (blade slots + config). Anything
      // they wrote themselves is their own content and must survive scrubbing —
      // otherwise a drainage company using this template would have its real
      // service names rewritten.
      let ownWords = '';
      try {
        const bits = [];
        for (const k of Object.keys(project.content || {})) {
          const c = project.content[k];
          if (c && Array.isArray(c.slots)) bits.push(c.slots.join(' '));
        }
        bits.push(JSON.stringify(project.config || {}));
        ownWords = bits.join(' ');
      } catch (e) { /* best effort */ }
      const profile = (opts && opts.identity) || Object.assign(
        __id.nxProfileFromPlan(Object.assign({}, project.config || {}, { name: project.name })),
        { ownWords });
      html = __id.nxScrubIdentity(html, profile);
      scrubbedJs = __id.nxScrubIdentity(script, profile);
    }
  } catch (e) { /* never break a render */ }

  return { html, css, js: scrubbedJs, valid: true, validationErrors: [], pageReady: true, tree: null, budget: null };
}

// Convenience composer: words -> { project, compiled } (graph is the runtime).
function nxBuildTemplateSite(words) {
  const project = nxTemplateProject(words);
  return { project, compiled: nxRenderTemplateDocument(project) };
}

